import{_ as e,o as s,c as n,a2 as o}from"./chunks/framework.D8Tso2Ul.js";const b=JSON.parse('{"title":"Módulo: Obras","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/obras.md","filePath":"modulos/obras.md"}'),t={name:"modulos/obras.md"};function i(d,a,r,c,l,p){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="modulo-obras" tabindex="-1">Módulo: Obras <a class="header-anchor" href="#modulo-obras" aria-label="Permalink to &quot;Módulo: Obras&quot;">​</a></h1><p><strong>Ubicación:</strong> <code>Frontend/src/pages/</code> · <code>Backend/handlers/obras-module/</code> · <code>lib/services/ObraService</code></p><p>Una <strong>obra</strong> es un proyecto de construcción gestionado por un tenant. Es la entidad central que agrupa documentos, actividades, incidentes y personas asignadas.</p><h2 id="que-es-una-obra-en-el-sistema" tabindex="-1">Qué es una obra en el sistema <a class="header-anchor" href="#que-es-una-obra-en-el-sistema" aria-label="Permalink to &quot;Qué es una obra en el sistema&quot;">​</a></h2><p>Cada obra (<code>ObrasTable</code>) registra:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>obraId        Identificador único</span></span>
<span class="line"><span>tenantId      Empresa propietaria</span></span>
<span class="line"><span>nombre        Nombre de la obra</span></span>
<span class="line"><span>codigo        Código interno opcional</span></span>
<span class="line"><span>direccion / comuna / region   Ubicación física</span></span>
<span class="line"><span>etapaActual   excavacion | obra_gruesa | terminaciones | entrega</span></span>
<span class="line"><span>mandante      Empresa mandante</span></span>
<span class="line"><span>estado        activa | pausada | finalizada</span></span>
<span class="line"><span>fasesConfig   Mapa de fases con sus documentos obligatorios</span></span></code></pre></div><p>Un tenant puede tener <strong>múltiples obras activas</strong> simultáneamente. La consulta de obras usa <code>PK = TENANT#{tenantId}</code>, por lo que se listan con Query (nunca Scan).</p><h2 id="ciclo-de-deming-vs-etapa-fisica" tabindex="-1">Ciclo de Deming vs. etapa física <a class="header-anchor" href="#ciclo-de-deming-vs-etapa-fisica" aria-label="Permalink to &quot;Ciclo de Deming vs. etapa física&quot;">​</a></h2><p>La obra avanza en dos dimensiones paralelas:</p><ul><li><strong>Etapa física</strong> (<code>etapaActual</code>): qué se está construyendo.</li><li><strong>Ciclo normativo (PDCA)</strong>: cómo se gestiona la prevención (Planificar, Hacer, Verificar, Actuar).</li></ul><p>El ciclo de Deming es <strong>normativo, no físico</strong>: una obra en etapa de <code>obra_gruesa</code> sigue ejecutando continuamente el ciclo de mejora. Ver <a href="/manual/ds44/fases-obra.html">Fases de obra</a>.</p><h2 id="creacion-de-una-obra" tabindex="-1">Creación de una obra <a class="header-anchor" href="#creacion-de-una-obra" aria-label="Permalink to &quot;Creación de una obra&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Admin / Prevencionista crea la obra (POST /obras)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. El sistema lee tenant.reglas.fasesObligatorias</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. Se precrean los documentos obligatorios de cada fase (fasesConfig)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4. El prevencionista sube los archivos a cada documento</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>5. La obra queda lista para asignar personas y registrar actividades</span></span></code></pre></div><h2 id="avance-de-fase" tabindex="-1">Avance de fase <a class="header-anchor" href="#avance-de-fase" aria-label="Permalink to &quot;Avance de fase&quot;">​</a></h2><p>Al cambiar <code>etapaActual</code>, la plataforma verifica si la fase anterior tiene todos sus documentos obligatorios en estado <code>completado</code>. Esto previene avanzar dejando brechas de cumplimiento.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Excavación ──▶ Obra gruesa ──▶ Terminaciones ──▶ Entrega</span></span>
<span class="line"><span>   (verifica docs obligatorios completos en cada transición)</span></span></code></pre></div><h2 id="endpoints-relacionados" tabindex="-1">Endpoints relacionados <a class="header-anchor" href="#endpoints-relacionados" aria-label="Permalink to &quot;Endpoints relacionados&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Método</th><th>Ruta</th><th>Acción</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/obras</code></td><td>Crear obra (precrea documentos)</td></tr><tr><td><code>GET</code></td><td><code>/obras</code></td><td>Listar obras del tenant</td></tr><tr><td><code>GET</code></td><td><code>/obras/{id}</code></td><td>Detalle de una obra</td></tr><tr><td><code>PUT</code></td><td><code>/obras/{id}</code></td><td>Actualizar obra</td></tr><tr><td><code>POST</code></td><td><code>/obras/{id}/phase-advance</code></td><td>Avanzar de fase con verificación</td></tr></tbody></table><p>Ver detalle en <a href="/manual/api/obras.html">API · Obras</a>.</p>`,19)])])}const m=e(t,[["render",i]]);export{b as __pageData,m as default};
